import { setTimeout as sleep } from 'node:timers/promises';

interface User { id: number; nome: string }

// async sempre devolve Promise: o tipo de retorno é Promise<User>
async function buscarUser(id: number): Promise<User> {
  await sleep(100); // simula I/O (banco, API)
  return { id, nome: 'Ana' };
}

const user = await buscarUser(1); // user: User (top-level await em ESM)
console.log(user.nome);           // 'Ana'

// Awaited desembrulha o tipo de dentro da Promise
type U = Awaited<ReturnType<typeof buscarUser>>; // User

// Esquecer o await é um bug comum, e o TS pega quando você usa o valor
const semAwait = buscarUser(2);
// @ts-expect-error: Promise<User> não tem .nome
console.log(semAwait.nome);

// Promise "solta" que rejeita vira unhandledRejection e derruba o processo.
// Ou dê await, ou trate com .catch:
buscarUser(3).catch((err: unknown) => console.error(err));

import { setTimeout as sleep } from 'node:timers/promises';

async function buscar<T>(valor: T, ms: number): Promise<T> {
  await sleep(ms);
  return valor;
}

// Sequencial: ~300ms (o segundo só começa quando o primeiro termina)
let t = Date.now();
const a = await buscar('user', 100);
const b = await buscar(42, 200);
console.log('sequencial', Date.now() - t, 'ms');

// Paralelo: ~200ms. Promise.all preserva o tipo de cada posição
t = Date.now();
const [user, total] = await Promise.all([buscar('user', 100), buscar(42, 200)]);
//     ^ string  ^ number
console.log('paralelo', Date.now() - t, 'ms');

// Promise.all rejeita inteiro se UMA falhar. allSettled espera todas:
const resultados = await Promise.allSettled([
  buscar('ok', 50),
  Promise.reject(new Error('fora do ar')),
]);
for (const r of resultados) {
  if (r.status === 'fulfilled') console.log('ok:', r.value); // união discriminada
  else console.log('falhou:', (r.reason as Error).message);
}

// Promise.race: a primeira que terminar (com sucesso ou erro) decide
console.log(await Promise.race([buscar('A', 100), buscar('B', 50)])); // 'B'

// Com "strict", a variável do catch é unknown: cheque antes de usar
try {
  JSON.parse('{ inválido');
} catch (err) {
  // @ts-expect-error: err é unknown, não dá para ler .message direto
  console.log(err.message);
  if (err instanceof SyntaxError) console.log('JSON quebrado');
}

// Classes de erro próprias carregam contexto e permitem instanceof
class HttpError extends Error {
  readonly status: number;
  constructor(status: number, message: string, options?: ErrorOptions) {
    super(message, options);
    this.name = 'HttpError';
    this.status = status;
  }
}

async function carregarPerfil(id: string) {
  try {
    throw new Error('ECONNRESET'); // simula a falha de rede original
  } catch (err) {
    // `cause` encadeia o erro original sem perder a stack dele
    throw new HttpError(502, `falha ao carregar perfil ${id}`, { cause: err });
  }
}

try {
  await carregarPerfil('u1');
} catch (err) {
  if (err instanceof HttpError) {
    console.log(err.status, err.message, '←', (err.cause as Error).message);
    // 502 falha ao carregar perfil u1 ← ECONNRESET
  }
}

import { readFile } from 'node:fs/promises';

type Result<T, E = Error> = { ok: true; value: T } | { ok: false; error: E };

// Erros esperados viram valor de retorno: quem chama é OBRIGADO a tratar
function parseIdade(texto: string): Result<number, 'vazio' | 'nao-numerico' | 'fora-da-faixa'> {
  if (texto.trim() === '') return { ok: false, error: 'vazio' };
  const n = Number(texto);
  if (!Number.isInteger(n)) return { ok: false, error: 'nao-numerico' };
  if (n < 0 || n > 150) return { ok: false, error: 'fora-da-faixa' };
  return { ok: true, value: n };
}

const r = parseIdade('42');
if (r.ok) console.log(r.value + 1); // r.value: number → 43
else console.log(r.error);          // r.error: 'vazio' | 'nao-numerico' | 'fora-da-faixa'

// Adaptador: transforma uma função que lança em uma que devolve Result
async function tentar<T>(fn: () => Promise<T>): Promise<Result<T>> {
  try {
    return { ok: true, value: await fn() };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err : new Error(String(err)) };
  }
}

const lido = await tentar(() => readFile('nao-existe.txt', 'utf8'));
if (!lido.ok) console.log('não deu:', lido.error.message);
// não deu: ENOENT: no such file or directory, open '.../nao-existe.txt'

// Regra prática: throw para bugs e falhas inesperadas;
// Result para erros de negócio que fazem parte do fluxo.

import { setTimeout as sleep } from 'node:timers/promises';

// Funções que aceitam AbortSignal podem ser canceladas de fora
async function tarefaLenta(signal?: AbortSignal): Promise<string> {
  await sleep(5_000, undefined, { signal }); // timers/promises respeita o signal
  return 'terminou';
}

// AbortSignal.timeout: aborta sozinho depois de N ms
const porTempo = AbortSignal.timeout(200);
try {
  await tarefaLenta(porTempo);
} catch (err) {
  // O timer rejeita com AbortError; o motivo real fica em signal.reason
  console.log((err as Error).name, '| motivo:', (porTempo.reason as Error).name);
  // AbortError | motivo: TimeoutError
}

// AbortController: você decide quando cancelar (usuário desistiu, SIGTERM...)
const controller = new AbortController();
setTimeout(() => controller.abort(new Error('cancelado pelo usuário')), 100);
try {
  await tarefaLenta(controller.signal);
} catch {
  console.log('motivo:', (controller.signal.reason as Error).message);
}

// Combine sinais: aborta no que acontecer primeiro
const ambos = AbortSignal.any([new AbortController().signal, AbortSignal.timeout(50)]);
await tarefaLenta(ambos).catch(() => console.log('abortado pelo timeout de 50ms'));

// fetch aceita o mesmo signal: await fetch(url, { signal: AbortSignal.timeout(2_000) })
